import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] secondLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(secondLine[i]) % m;
        }

        Set<Integer> x = new HashSet<>();
        Set<Integer> y = new HashSet<>();

        generateSubsets(a, x, 0, n / 2, 0, m);
        generateSubsets(a, y, n / 2, n, 0, m);

        List<Integer> yList = new ArrayList<>(y);
        Collections.sort(yList);

        int result = 0;
        for (int i : x) {
            int target = m - i;
            int pos = Collections.binarySearch(yList, target);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos > 0) {
                int candidate = i + yList.get(pos - 1);
                if (candidate > result) {
                    result = candidate;
                }
            }
        }
        System.out.println(result);
    }

    private static void generateSubsets(int[] a, Set<Integer> s, int start, int end, int currentSum, int m) {
        if (start == end) {
            s.add(currentSum % m);
        } else {
            generateSubsets(a, s, start + 1, end, (currentSum + a[start]) % m, m);
            generateSubsets(a, s, start + 1, end, currentSum, m);
        }
    }
}
